before:
function describeShutdownImpact(summary) {
  const localAgents = summary.acpSessions + summary.localTuiSessions;
  const impacts = [];
  if (localAgents > 0) {
    impacts.push(`${localAgents} running agent ${localAgents === 1 ? "session" : "sessions"}`);
  }
  if (summary.terminals > 0) {
    impacts.push(`${summary.terminals} ${summary.terminals === 1 ? "terminal" : "terminals"}`);
  }
  const stopped = impacts.length > 0 ? `${summary.incomplete ? "At least " : ""}${impacts.join(" and ")} may be stopped.` : summary.incomplete ? "Running agent sessions and terminals may be stopped." : "Background services and automations will stop.";
  const remote2 = summary.remoteSessions > 0 ? ` ${summary.incomplete ? "At least " : ""}${summary.remoteSessions} remote ${summary.remoteSessions === 1 ? "session" : "sessions"} will keep running.` : "";
  return `${stopped}${remote2}`;
}

after:
function describeShutdownImpact(summary) {
  const localAgents = summary.acpSessions + summary.localTuiSessions;
  const impacts = [];
  if (localAgents > 0) impacts.push(`${localAgents} 个正在运行的代理会话`);
  if (summary.terminals > 0) impacts.push(`${summary.terminals} 个终端`);
  const stopped = impacts.length > 0 ? `${summary.incomplete ? "至少 " : ""}${impacts.join("和")}可能会停止。` : summary.incomplete ? "正在运行的代理会话和终端可能会停止。" : "后台服务和自动化将停止。";
  const remote2 = summary.remoteSessions > 0 ? ` ${summary.incomplete ? "至少 " : ""}${summary.remoteSessions} 个远程会话将继续运行。` : "";
  return `${stopped}${remote2}`;
}

